use revm_interpreter::{Interpreter, InstructionContext};
use revm_interpreter::interpreter::EthInterpreter;
pub fn add(interpreter: &mut Interpreter<EthInterpreter>) {
    revm_interpreter::instructions::arithmetic::add(InstructionContext { interpreter, host: &mut () });
}
pub fn sub(interpreter: &mut Interpreter<EthInterpreter>) {
    revm_interpreter::instructions::arithmetic::sub(InstructionContext { interpreter, host: &mut () });
}

